import heapq

def dijkstra(graph, source):
    """
    Args:
        graph: dict of dict, e.g. {A: {B: 1, C: 4}, B: {C: 2}, C: {}}
        source: starting node
    Returns:
        (distances, predecessors) where distances maps each node to its
        shortest distance from source, and predecessors maps each node to
        the previous node on the shortest path (None for source/unreachable).
    """
    distances = {node: float('inf') for node in graph}
    for neighbors in graph.values():
        for n in neighbors:
            if n not in distances:
                distances[n] = float('inf')
    distances[source] = 0

    predecessors = {node: None for node in distances}
    visited = set()
    heap = [(0, source)]

    while heap:
        dist, current = heapq.heappop(heap)
        if current in visited:
            continue
        visited.add(current)
        for neighbor, weight in graph[current].items():
            new_dist = dist + weight
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                predecessors[neighbor] = current
                heapq.heappush(heap, (new_dist, neighbor))

    return distances, predecessors
